CREATE COLUMN TABLE "TEST_AP"."OSEC" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(15) NOT NULL , "Descr" NVARCHAR(30), "eCode" NVARCHAR(3) NOT NULL , PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSEC_CODE" ON "TEST_AP"."OSEC" ( "Code" ASC );
CREATE UNIQUE INDEX "OSEC_ECODE" ON "TEST_AP"."OSEC" ( "eCode" ASC )